pub fn decode(data: &[u8]) -> Result<Request, Refusal> {
    let mut r = Reader { buf: data, pos: 0, depth: 0 };
    r.skip_ws();
    let v = decode_request(&mut r)?;
    r.skip_ws();
    if r.pos < r.buf.len() {
        return r.refuse("trailing_bytes");
    }
    Ok(v)
}

// REFUSALS is in the order two of them are chosen between.
pub const REFUSALS: [&str; 11] = ["malformed", "bad_string", "number_spelling", "wrong_type", "depth_exceeded", "duplicate_key", "duplicate_field", "unknown_field", "missing_field", "bad_enum", "trailing_bytes"];

pub fn refusal_rank(word: &str) -> i32 {
    match REFUSALS.iter().position(|w| *w == word) {
        Some(i) => i as i32,
        None => -1,
    }
}

#[allow(unused_variables)]
fn service_check_request(v: &Request) -> Result<(), Refusal> {
    let r = Reader { buf: &[], pos: 0, depth: 0 };
    Ok(())
}

#[allow(unused_variables)]
fn service_check_appmetadata(v: &AppMetadata) -> Result<(), Refusal> {
    let r = Reader { buf: &[], pos: 0, depth: 0 };
    Ok(())
}

#[allow(unused_variables)]
fn service_check_holdmetadata(v: &HoldMetadata) -> Result<(), Refusal> {
    let r = Reader { buf: &[], pos: 0, depth: 0 };
    Ok(())
}

#[allow(unused_variables)]
fn service_check_responsemetadata(v: &ResponseMetadata) -> Result<(), Refusal> {
    let r = Reader { buf: &[], pos: 0, depth: 0 };
    if let Some(value) = &v.app { service_check_appmetadata(value)?; }
    for value in &v.apps { service_check_appmetadata(value)?; }
    for value in &v.holds { service_check_holdmetadata(value)?; }
    Ok(())
}

#[allow(unused_variables)]
fn service_check_subject(v: &Subject) -> Result<(), Refusal> {
    let r = Reader { buf: &[], pos: 0, depth: 0 };
    Ok(())
}

#[allow(unused_variables)]
fn service_check_decision(v: &Decision) -> Result<(), Refusal> {
    let r = Reader { buf: &[], pos: 0, depth: 0 };
    if v.outcome != "permitted" && v.outcome != "denied" && v.outcome != "not_granted" && v.outcome != "unknown_action" && v.outcome != "invalid" && v.outcome != "forbidden" && v.outcome != "unavailable" { return r.refuse("bad_enum"); }
    Ok(())
}

#[allow(unused_variables)]
fn service_check_policyrule(v: &PolicyRule) -> Result<(), Refusal> {
    let r = Reader { buf: &[], pos: 0, depth: 0 };
    service_check_subject(&v.subject)?;
    Ok(())
}

#[allow(unused_variables)]
fn service_check_policypage(v: &PolicyPage) -> Result<(), Refusal> {
    let r = Reader { buf: &[], pos: 0, depth: 0 };
    if v.outcome != "page" && v.outcome != "gap" && v.outcome != "invalid" && v.outcome != "forbidden" && v.outcome != "unavailable" { return r.refuse("bad_enum"); }
    for value in &v.rules { service_check_policyrule(value)?; }
    Ok(())
}

